import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams, useNavigate } from "react-router-dom";

const AdminFProf = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [professor, setProfessor] = useState(null);
  const [cursos, setCursos] = useState([]);
  const [cursoSelecionado, setCursoSelecionado] = useState("");

  useEffect(() => {
    const fetchProfessor = async () => {
      try {
        const res = await fetch(`http://localhost:5000/professores/${id}`);
        if (res.ok) {
          const data = await res.json();
          console.log("Dados do professor:", data); 
          setProfessor(data);
          setCursoSelecionado(data.cursoId || "");
        }
      } catch (error) {
        console.error("Erro ao buscar professor:", error);
      }
    };

    const fetchCursos = async () => {
      try {
        const res = await fetch("http://localhost:5000/cursos");
        if (res.ok) {
          const data = await res.json();
          setCursos(data);
        }
      } catch (error) {
        console.error("Erro ao buscar cursos:", error);
      }
    };

    fetchProfessor();
    fetchCursos();
  }, [id]);

  const atualizarCurso = async () => {
    try {
      const res = await fetch(`http://localhost:5000/professores/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ cursoId: cursoSelecionado }),
      });
      if (res.ok) {
        alert("Curso atualizado com sucesso!");
        navigate("/admlistprof");
      } else {
        alert("Erro ao atualizar curso");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  if (!professor) return <p>Carregando...</p>;

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistcurso">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Alunos
          </a>
        </li>
      </ul>

      <h3 className="mt-4">Detalhes do Professor</h3>
      <p>
        <strong>Nome:</strong> {professor.nome}
      </p>
      <p>
        <strong>Email:</strong> {professor.email}
      </p>

      <div className="mt-3">
        <label>
          <strong>Curso:</strong>
        </label>
        <select
          className="form-control mt-2"
          value={cursoSelecionado}
          onChange={(e) => setCursoSelecionado(e.target.value)}
        >
          <option value="">Selecione um curso</option>
          {cursos.map((curso) => (
            <option key={curso.id} value={curso.id}>
              {curso.nome}
            </option>
          ))}
        </select>
      </div>

      <button className="btn btn-success mt-3" onClick={atualizarCurso}>
        Atualizar Curso
      </button>

      <button
        className="btn btn-secondary mt-3 mx-2"
        onClick={() => navigate("/admlistprof")}
      >
        Voltar
      </button>
    </div>
  );
};

export default AdminFProf;
